"""Thread-safe token bucket rate limiter."""

import threading
import time


class TokenBucketLimiter:
    """Rate limiter using the token bucket algorithm.

    Tokens accumulate at `refill_rate` tokens per second, up to a
    maximum of `capacity`. Each call to `allow()` attempts to consume
    `cost` tokens; it succeeds only if enough tokens are available.

    Safe to share across threads.
    """

    def __init__(self, capacity, refill_rate):
        if capacity <= 0:
            raise ValueError("capacity must be positive")
        if refill_rate <= 0:
            raise ValueError("refill_rate must be positive")
        self._capacity = float(capacity)
        self._refill_rate = float(refill_rate)
        self._tokens = float(capacity)
        self._last_check = time.monotonic()
        self._lock = threading.Lock()

    def _refill(self):
        # Must be called while holding self._lock.
        now = time.monotonic()
        elapsed = now - self._last_check
        self._last_check = now
        if elapsed > 0:
            self._tokens = min(
                self._capacity, self._tokens + elapsed * self._refill_rate
            )

    def allow(self, cost=1.0):
        """Attempt to consume `cost` tokens.

        Returns True and deducts the tokens if enough are available,
        otherwise returns False and leaves the bucket unchanged.
        """
        if cost <= 0:
            raise ValueError("cost must be positive")
        with self._lock:
            self._refill()
            if self._tokens >= cost:
                self._tokens -= cost
                return True
            return False

    def available_tokens(self):
        """Return the current token count without consuming any."""
        with self._lock:
            self._refill()
            return self._tokens


def rate_limited(limiter, cost=1.0):
    """Decorator that rejects calls when the limiter denies them.

    Raises RuntimeError instead of calling the wrapped function when
    there are not enough tokens available.
    """

    def decorator(func):
        def wrapper(*args, **kwargs):
            if not limiter.allow(cost):
                raise RuntimeError("rate limit exceeded")
            return func(*args, **kwargs)

        return wrapper

    return decorator


if __name__ == "__main__":
    limiter = TokenBucketLimiter(capacity=5, refill_rate=1)

    @rate_limited(limiter)
    def fetch_page(url):
        return "fetched {}".format(url)

    for i in range(7):
        try:
            print(fetch_page("https://example.com/{}".format(i)))
        except RuntimeError as exc:
            print("request {} blocked: {}".format(i, exc))
